"""A semantically frozen screen is recorded even while input keeps changing.

#4528: the g1190 defence egg battle held one readable command box for 2.5 h
while A was sent every observation; #4542 held a price-confirm screen with
alternating A/B. The run-level two-digest ring and the exact-cycle repetition
detector see neither. The record is observation-only -- no input is changed.
"""
from docich.hanjuku_speedrun.hanjuku import orchestrator as O
from docich.hanjuku_speedrun.hanjuku.os_layer.font import TextLine
from docich.hanjuku_speedrun.hanjuku.os_layer.screen import Screen


def box(text='もうこうげきたまごをつかう', cursor=208):
    screen = Screen([], None, text, kind='egg_battle_menu')
    screen.menu_rows = [
        TextLine(176, tuple((176 + 8 * i, ch) for i, ch in enumerate('もうこうげき'))),
        TextLine(192, tuple((176 + 8 * i, ch) for i, ch in enumerate('たまごをつかう'))) ]
    screen.menu_cursor = cursor
    return screen


def records(mem):
    return [r for r in mem.get('_records', []) if r['decision'] == 'semantic_stall_observed']


def test_one_record_per_episode_after_the_bound():
    mem = {}
    screen = box()
    for _ in range(O.SEMANTIC_STALL_OBSERVATIONS - 1):
        assert O.semantic_stall_observe(mem, 'event', 'egg_battle_menu', screen) is None
        assert not records(mem)
    O.semantic_stall_observe(mem, 'event', 'egg_battle_menu', screen)
    assert len(records(mem)) == 1
    record = records(mem)[0]
    assert record['screen'] == 'egg_battle_menu'
    assert record['phase'] == 'event'
    assert record['observed_metric']['text'] == 'もうこうげきたまごをつかう'
    assert record['observed_metric']['menu_rows'][0][0] == 176
    # The record stays one per episode; it does not repeat every observation.
    for _ in range(O.SEMANTIC_STALL_OBSERVATIONS * 2):
        O.semantic_stall_observe(mem, 'event', 'egg_battle_menu', screen)
    assert len(records(mem)) == 1


def test_input_is_not_part_of_the_key():
    # The function never sees the pressed buttons: A repeats and A/B alternation
    # are the same semantic episode. A blinking cursor/digest is likewise out.
    mem = {}
    screen = box()
    for cursor in (208, 192, 208, 192):
        for _ in range(O.SEMANTIC_STALL_OBSERVATIONS // 4):
            screen.menu_cursor = cursor  # the key uses row labels, not the cursor
            O.semantic_stall_observe(mem, 'event', 'egg_battle_menu', screen)
    assert len(records(mem)) == 1


def test_a_changed_text_or_phase_starts_a_new_episode():
    mem = {}
    O.semantic_stall_observe(mem, 'event', 'battle_menu', box())
    changed = box(text='another line')
    for _ in range(O.SEMANTIC_STALL_OBSERVATIONS - 1):
        O.semantic_stall_observe(mem, 'event', 'battle_menu', changed)
    assert not records(mem)
    O.semantic_stall_observe(mem, 'event', 'battle_menu', changed)
    assert len(records(mem)) == 1
    # A phase change resets again without emitting immediately.
    O.semantic_stall_observe(mem, 'battle', 'battle_menu', changed)
    assert mem['semantic_stall_watch']['n'] == 1
    assert len(records(mem)) == 1


def test_bounded_wait_and_unreadable_screens_are_not_recorded():
    mem = {}
    for _ in range(O.SEMANTIC_STALL_OBSERVATIONS * 2):
        O.semantic_stall_observe(mem, 'event', 'battle_menu', box(), guarded=True)
    assert not records(mem)
    assert 'semantic_stall_watch' not in mem
    for _ in range(O.SEMANTIC_STALL_OBSERVATIONS * 2):
        O.semantic_stall_observe(mem, 'field', 'map', Screen([], None, ''))
    assert not records(mem)
